import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788283338000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="get-document-returned-empty-—-or-it-never-existed" tabindex="-1"><code>get_document</code> returned &quot;empty — or it never existed&quot; <a class="header-anchor" href="#get-document-returned-empty-—-or-it-never-existed" aria-label="Permalink to “get_document returned &quot;empty — or it never existed&quot;”">​</a></h2><p>That is Rustpad, not the server: <code>GET /api/text/{id}</code> answers an empty string for an empty pad, a pad that never existed, and one that expired. The three cases are indistinguishable over the API. If you expected content, the pad has most likely expired — documents are dropped after 24 hours without an open connection and on every server restart, unless the instance runs with <code>SQLITE_URI</code>.</p><h2 id="the-rustpad-websocket-connection-failed" tabindex="-1">&quot;the Rustpad WebSocket connection failed&quot; <a class="header-anchor" href="#the-rustpad-websocket-connection-failed" aria-label="Permalink to “&quot;the Rustpad WebSocket connection failed&quot;”">​</a></h2><p>The HTTP endpoints worked but the socket did not (or vice versa) — almost always a reverse-proxy issue. The proxy in front of Rustpad must forward WebSocket upgrades on <code>/api/socket/…</code>. In nginx terms: <code>proxy_set_header Upgrade $http_upgrade; proxy_set_header Connection &quot;upgrade&quot;;</code>.</p><h2 id="replace-in-document-says-the-string-occurs-n-times" tabindex="-1"><code>replace_in_document</code> says the string occurs N times <a class="header-anchor" href="#replace-in-document-says-the-string-occurs-n-times" aria-label="Permalink to “replace_in_document says the string occurs N times”">​</a></h2><p>By default the search string must match exactly once, so the model cannot accidentally rewrite more than it looked at. Either make the search string longer (include surrounding context) or pass <code>replace_all: true</code> deliberately.</p><h2 id="why-did-a-dialog-appear-before-set-document" tabindex="-1">Why did a dialog appear before <code>set_document</code>? <a class="header-anchor" href="#why-did-a-dialog-appear-before-set-document" aria-label="Permalink to “Why did a dialog appear before set_document?”">​</a></h2><p>Replacing a non-empty pad destroys content that cannot be restored, so a person is asked first. <code>replace_in_document</code> asks too, but only when <code>replace_all</code> is about to change more than one place. For a single targeted change, and for <code>append_to_document</code>, nothing is asked — those are also the tools that play nicely with concurrent human edits.</p><h2 id="a-tool-answered-with-a-confirm-token-instead-of-asking" tabindex="-1">A tool answered with a <code>confirm_token</code> instead of asking <a class="header-anchor" href="#a-tool-answered-with-a-confirm-token-instead-of-asking" aria-label="Permalink to “A tool answered with a confirm_token instead of asking”">​</a></h2><p>That is the fallback for a client that cannot show a dialog. Call the tool again with the same arguments plus the token; it is single-use and lasts five minutes. See <a href="/guide/approval">Asking a person</a> for what it does and does not prove — and if your client <em>can</em> show dialogs, check whether <code>ELICITATION</code> is set to <code>false</code> somewhere in the environment. It is not prefixed, so it may have been meant for a different server.</p><h2 id="someone-saw-rustpad-mcp-in-their-pad" tabindex="-1">Someone saw &quot;rustpad-mcp&quot; in their pad <a class="header-anchor" href="#someone-saw-rustpad-mcp-in-their-pad" aria-label="Permalink to “Someone saw &quot;rustpad-mcp&quot; in their pad”">​</a></h2><p>Working as intended: while editing, the server announces itself as a collaborator named <code>rustpad-mcp</code>, so humans in the pad can see that a machine is typing. It disconnects as soon as the tool call finishes.</p><h2 id="can-it-list-all-pads" tabindex="-1">Can it list all pads? <a class="header-anchor" href="#can-it-list-all-pads" aria-label="Permalink to “Can it list all pads?”">​</a></h2><p>No — Rustpad has no such API. Pads exist implicitly under every id; you have to know the ids you care about. <code>get_stats</code> tells you how many documents the server currently holds, but not their names.</p><h2 id="text-with-emoji-ends-up-mangled" tabindex="-1">Text with emoji ends up mangled <a class="header-anchor" href="#text-with-emoji-ends-up-mangled" aria-label="Permalink to “Text with emoji ends up mangled”">​</a></h2><p>It should not — positions are counted in Unicode code points end to end, and the test suite covers astral characters explicitly. If you can reproduce a mangling, that is a bug: please open an issue with the exact before/after text.</p><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>RUSTPAD_READ_ONLY</code> is set, and it is a write tool.</li><li><code>RUSTPAD_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>RUSTPAD_DENY_TOOLS</code> names it, possibly through a prefix such as <code>list_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot;. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};